// Port of the supplied PROJECTION-CONCURRENCE-029 contract. Endpoint-only uncertainty.
export const EPS=1e-12;
export const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]],dot=(a,b)=>a.reduce((n,v,i)=>n+v*b[i],0);
export function unit(v){const n=Math.sqrt(dot(v,v));if(n<EPS)throw Error('Zero vector');const q=v.map(x=>x/n),k=q.reduce((best,x,i)=>Math.abs(x)>Math.abs(q[best])?i:best,0);return q[k]>=0?q:q.map(x=>-x);}
export function eigensystem(matrix){const a=matrix.map(r=>r.slice()),v=Array.from({length:3},(_,i)=>Array.from({length:3},(_,j)=>+(i===j)));for(let iter=0;iter<100;iter++){const[p,q]=[[0,1],[0,2],[1,2]].reduce((b,p)=>Math.abs(a[p[0]][p[1]])>Math.abs(a[b[0]][b[1]])?p:b);if(Math.abs(a[p][q])<=1e-15*Math.max(1,a.reduce((n,r,i)=>n+Math.abs(r[i]),0)))break;const tau=(a[q][q]-a[p][p])/(2*a[p][q]),t=(tau>=0?1:-1)/(Math.abs(tau)+Math.sqrt(1+tau*tau)),c=1/Math.sqrt(1+t*t),s=t*c,app=a[p][p],aqq=a[q][q],apq=a[p][q];a[p][p]=app-t*apq;a[q][q]=aqq+t*apq;a[p][q]=a[q][p]=0;for(let k=0;k<3;k++){if(k!==p&&k!==q){const akp=a[k][p],akq=a[k][q];a[k][p]=a[p][k]=c*akp-s*akq;a[k][q]=a[q][k]=s*akp+c*akq;}const vp=v[k][p],vq=v[k][q];v[k][p]=c*vp-s*vq;v[k][q]=s*vp+c*vq;}}
return[0,1,2].map(i=>({value:a[i][i],vector:unit(v.map(r=>r[i]))})).sort((a,b)=>a.value-b.value);}
export const normalize=(p,w,h)=>[(p[0]-w/2)/Math.max(w,h),(p[1]-h/2)/Math.max(w,h),1];
export function imageSource(s,w,h){const scale=Math.max(w,h);return unit([s[0]*scale+s[2]*w/2,s[1]*scale+s[2]*h/2,s[2]]);}
export function line(a,g){const l=cross(a,g),n=Math.hypot(l[0],l[1]);if(n<EPS)throw Error('Collapsed aperture/receiver segment');return l.map(x=>x/n);}
export function validateInput(pairs,w,h,training){const point=p=>Array.isArray(p)&&p.length===2&&p.every(x=>typeof x==='number'&&Number.isFinite(x));if(!Number.isFinite(w)||!Number.isFinite(h)||w<=0||h<=0||!Array.isArray(pairs)||pairs.length<2||pairs.length>1000)throw Error('Positive image dimensions and at least two pairs required');if(!Array.isArray(training)||training.length<2||new Set(training).size!==training.length||training.some(i=>!Number.isInteger(i)||i<0||i>=pairs.length))throw Error('At least two distinct valid training indices required');for(const p of pairs){if(!point(p.aperture)||!point(p.receiver)||!Number.isFinite(p.sigma_px)||p.sigma_px<=0)throw Error('Finite endpoints and positive pick uncertainty required');line(normalize(p.aperture,w,h),normalize(p.receiver,w,h));}}
export function fit(pairs,w,h,training){validateInput(pairs,w,h,training);const lines=training.map(i=>line(normalize(pairs[i].aperture,w,h),normalize(pairs[i].receiver,w,h))),scatter=Array.from({length:3},(_,i)=>Array.from({length:3},(_,j)=>lines.reduce((n,l)=>n+l[i]*l[j],0))),e=eigensystem(scatter),values=e.map(x=>x.value),s=e[0].vector,gap=(values[1]-values[0])/Math.max(EPS,values[2]),warnings=[];if(gap<1e-7)warnings.push('nonunique_or_ill_conditioned_source');if(training.length<3)warnings.push('two_lines_determine_intersection_without_redundancy');const px=imageSource(s,w,h);return{source_normalized_homogeneous:s,source_image_homogeneous:px,source_image_finite:Math.abs(px[2])<EPS?null:[px[0]/px[2],px[1]/px[2]],eigenvalues:values,relative_eigen_gap:gap,warnings,training_indices:training.slice()};}
export function residual(pair,s,w,h,factor=1){const a=normalize(pair.aperture,w,h),g=normalize(pair.receiver,w,h),l=cross(a,g),f=dot(l,s),grad=[-s[1]+g[1]*s[2],s[0]-g[0]*s[2],s[1]-a[1]*s[2],-s[0]+a[0]*s[2]],sigma=pair.sigma_px*factor/Math.max(w,h);if(!Number.isFinite(sigma)||sigma<=0)throw Error('Positive pick sigma required');const variance=sigma*sigma*dot(grad,grad),pred=cross(a,s),n=Math.hypot(pred[0],pred[1]);if(n<EPS)return{status:'source_coincident_with_aperture_or_degenerate',signed_miss_px:null,endpoint_standardized:null,endpoint_sigma_miss_px:null};return{status:'ok',signed_miss_px:dot(pred,g)/n*Math.max(w,h),endpoint_standardized:variance<EPS**2?null:f/Math.sqrt(variance),endpoint_sigma_miss_px:Math.sqrt(variance)/n*Math.max(w,h)};}
export function diagnose(pairs,w,h,training){const result=fit(pairs,w,h,training),rows=pairs.map((p,i)=>({...residual(p,result.source_normalized_homogeneous,w,h),index:i,role:training.includes(i)?'training':'heldout'})),held=rows.filter(r=>r.role==='heldout'),okay=held.length&&held.every(r=>r.status==='ok');return{fit:result,residuals:rows,heldout_miss_rms_px:okay?Math.sqrt(held.reduce((n,r)=>n+r.signed_miss_px**2,0)/held.length):null,heldout_endpoint_only_rms:okay&&held.every(r=>r.endpoint_standardized!==null)?Math.sqrt(held.reduce((n,r)=>n+r.endpoint_standardized**2,0)/held.length):null,uncertainty:'endpoint-only; omits source-fit uncertainty and shared model error; not a confidence or p-value',real_data_admission:false};}
export function prediction(pair,source){const p=cross([...pair.aperture,1],source),n=Math.hypot(p[0],p[1]);if(n<EPS)return null;const l=p.map(x=>x/n),miss=dot(l,[...pair.receiver,1]);return{line:l,signedMiss:miss,perpendicularFoot:[pair.receiver[0]-miss*l[0],pair.receiver[1]-miss*l[1]]};}
